// Package stickers holds the platform sticker catalog (MSG-STICKER-01,
// ADR-0047). The catalog is reference data generated by
// apps/web/scripts/generate-sticker-catalog.mjs together with the same-origin
// WebP files under apps/web/public/stickers/, embedded into the Core API
// binary and validated once when the package is initialized.
package stickers

import _ "embed"

//go:embed catalog.json
var catalogJSON []byte
